function transformURL() {
  var oid = (typeof parameters !== 'undefined' && parameters && parameters.orderId != null)
    ? parameters.orderId
    : '{{parameters.orderId}}';

  var orderId = oid;

  if (orderId && typeof orderId === 'object') {
    orderId = orderId.value || orderId.id || orderId.orderId || (orderId.data && (orderId.data.value || orderId.data.id || orderId.data.orderId));
  }

  if (typeof orderId === 'string') {
    var raw = orderId.trim().replace(/^"|"$/g, '');
    if ((raw[0] === '{' && raw[raw.length - 1] === '}') || (raw[0] === '[' && raw[raw.length - 1] === ']')) {
      try {
        var obj = JSON.parse(raw);
        if (Array.isArray(obj)) obj = obj[0];
        orderId = obj && typeof obj === 'object'
          ? obj.value || obj.id || obj.orderId || (obj.data && (obj.data.value || obj.data.id || obj.data.orderId)) || raw
          : raw;
      } catch (e) {
        orderId = raw;
      }
    } else {
      orderId = raw;
    }
  }

  if (!orderId || orderId === '[object Object]') throw new Error('Invalid orderId');

  return (url.endsWith('/') ? url : url + '/') + encodeURIComponent(String(orderId)) + '/payments';
}
return transformURL();
